-- Finding (thermite idx 223): the relcache trigger-descriptor reader panicked
-- on TOASTed tgargs (>2KB trigger arguments) because it read the raw TOAST
-- bytes instead of detoasting. DML and pg_trigger reads must work.
CREATE TABLE thermite_tr(a int);
CREATE FUNCTION thermite_trf() RETURNS trigger LANGUAGE plpgsql AS 46987 BEGIN RETURN NEW; END 46987;
CREATE TRIGGER thermite_trt BEFORE INSERT ON thermite_tr FOR EACH ROW
  EXECUTE FUNCTION thermite_trf('');
INSERT INTO thermite_tr VALUES (1);
SELECT tgnargs, length(tgargs) FROM pg_trigger WHERE tgname = 'thermite_trt';
DROP TABLE thermite_tr;
DROP FUNCTION thermite_trf();
